#include <bits/stdc++.h>
using namespace std;

long long total_finish(const vector<int>& order) {
    long long now = 0, total = 0;          // 합이 커질 수 있어 long long
    for (int x : order) {
        now += x;
        total += now;
    }
    return total;
}

int main() {
    int n;
    cin >> n;
    vector<int> t(n);
    for (auto& x : t) cin >> x;
    cout << total_finish(t) << '\n';       // 들어온 순서대로
    vector<int> order = t;
    sort(order.begin(), order.end());      // 짧은 작업 먼저
    for (int i = 0; i < n; i++) cout << order[i] << (i + 1 == n ? '\n' : ' ');
    cout << total_finish(order) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int greedy(vector<int> coins, int x) {
    sort(coins.begin(), coins.end(), greater<>());   // 큰 동전부터
    int cnt = 0;
    for (int c : coins) {
        cnt += x / c;
        x %= c;
    }
    return cnt;
}

int best(const vector<int>& coins, int x) {
    const int INF = 1e9;
    vector<int> dp(x + 1, INF);
    dp[0] = 0;
    for (int v = 1; v <= x; v++)
        for (int c : coins)
            if (c <= v && dp[v - c] != INF) dp[v] = min(dp[v], dp[v - c] + 1);
    return dp[x];
}

int main() {
    for (vector<int> coins : {vector<int>{1, 5, 10, 50}, vector<int>{1, 3, 4}}) {
        cout << "그리디가 틀리는 금액:";
        for (int x = 1; x <= 30; x++)
            if (greedy(coins, x) != best(coins, x)) cout << ' ' << x;
        cout << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Job { long long t, w; };   // 걸리는 시간, 중요도

long long cost(const vector<Job>& order) {
    long long now = 0, total = 0;
    for (auto& j : order) {
        now += j.t;
        total += j.w * now;               // 끝나는 시각 × 중요도
    }
    return total;
}

int main() {
    vector<Job> jobs = {{3, 1}, {1, 4}, {2, 2}, {4, 3}, {2, 5}};
    vector<Job> order = jobs;
    sort(order.begin(), order.end(), [](const Job& a, const Job& b) {
        return a.t * b.w < b.t * a.w;     // 엄격한 <, 곱은 long long
    });
    for (auto& j : order) cout << '(' << j.t << ',' << j.w << ") ";
    cout << cost(order) << '\n';

    vector<int> idx(jobs.size());
    iota(idx.begin(), idx.end(), 0);
    long long best = LLONG_MAX;
    do {                                  // 작은 입력은 완전탐색으로 확인
        vector<Job> o;
        for (int i : idx) o.push_back(jobs[i]);
        best = min(best, cost(o));
    } while (next_permutation(idx.begin(), idx.end()));
    cout << best << '\n';
    return 0;
}
